type Node = { readonly kind: "leaf"; readonly text: string }
          | { readonly kind: "branch"; readonly kids: readonly Node[] };

type Frame = { readonly parent: Node; readonly index: number };   // one hole per level
type Loc = { readonly focus: Node; readonly path: readonly Frame[] };

function up(l: Loc): Loc | undefined {
  const f = l.path[l.path.length - 1];
  if (!f || f.parent.kind !== "branch") return undefined;           // root: partial
  const kids = f.parent.kids.map((k, i) => (i === f.index ? l.focus : k));
  return { focus: { kind: "branch", kids }, path: l.path.slice(0, -1) };
}

