import { zipper, type ZipperOps } from "@thi.ng/zipper";

const ops: ZipperOps<number[]> = {
  branch: (n) => Array.isArray(n),
  children: (n) => (Array.isArray(n) ? n : []),
  factory: (_n, kids) => kids,
};

const edited = zipper([1, [5, 4, 3, 2], 6], ops)
  .next.next.down.rightmost.remove().up.up.appendChild(7).root;
